import { useState, KeyboardEvent } from 'react';
import { JxTextField, JxTag, JxButton, JxStack } from '@jinx-ui/react';

interface TagInputProps {
  onChange?: (tags: string[]) => void;
}

export default function TagInput({ onChange }: TagInputProps) {
  const [tags, setTags] = useState<string[]>([]);
  const [inputValue, setInputValue] = useState('');

  const updateTags = (next: string[]) => {
    setTags(next);
    onChange?.(next);
  };

  const addTag = (rawValue: string) => {
    const value = rawValue.trim();
    if (!value || tags.includes(value)) {
      setInputValue('');
      return;
    }
    updateTags([...tags, value]);
    setInputValue('');
  };

  const removeTag = (tagToRemove: string) => {
    updateTags(tags.filter((tag) => tag !== tagToRemove));
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter' || event.key === ',') {
      event.preventDefault();
      addTag(inputValue);
    } else if (event.key === 'Backspace' && inputValue === '' && tags.length > 0) {
      updateTags(tags.slice(0, -1));
    }
  };

  return (
    <JxStack direction="column" gap="var(--jx-space-2)" className="jx-tag-input">
      <JxTextField
        value={inputValue}
        onValueChange={setInputValue}
        onKeyDown={handleKeyDown}
        onBlur={() => addTag(inputValue)}
        placeholder="Введите тег и нажмите Enter"
        aria-label="Добавить тег"
      />
      <JxStack direction="row" wrap gap="var(--jx-space-1)" className="jx-tag-input__tags">
        {tags.map((tag) => (
          <JxTag key={tag} variant="subtle">
            {tag}
            <JxButton
              variant="ghost"
              size="sm"
              aria-label={`Удалить тег ${tag}`}
              onClick={() => removeTag(tag)}
            >
              ×
            </JxButton>
          </JxTag>
        ))}
      </JxStack>
    </JxStack>
  );
}

